def facts():
    return deepcopy(EXPECTED)


def validate_contract(contract=None,source_bindings=None):
    actual=strict_json(PATH.read_bytes()) if contract is None else deepcopy(contract)
    oracle._equal(actual,facts(),'contract/independent_closed_facts')
    supplied={r['path']:r for r in source_bindings} if source_bindings is not None else None
    for row in EXPECTED['sourceBindings']:
        raw=(ROOT/row['path']).read_bytes()
        if len(raw)!=row['bytes'] or sha256(raw).hexdigest()!=row['sha256']:
            raise ValueError('ReviewedCalRtSemanticSourceChanged:'+row['path'])
        if supplied is not None and (row['path'] not in supplied or any(supplied[row['path']][k]!=row[k] for k in ('bytes','sha256'))):
            raise ValueError('CurrentSourceJoinMissingReviewedBinding:'+row['path'])
    cases=list(corpus.iter_cases()); expected=[oracle.expected_case(c) for c in cases]
    oracle._equal(corpus.coverage()['retirements'],656,'contract/independent_retirement_count')
    oracle._equal(sum(e['instruction_count'] for e in expected),656,'contract/full41_oracles')
    oracle._equal(sum(e['stack_frame']['same_value'] for e in expected),4,'contract/equal_canary_still_fresh_frame')
    for e in expected:
        oracle._equal(len([r for r in e['all_native_journal'] if r[4]==1]),15,'contract/all_native15writes')
        oracle._equal(len(e['steps']),41,'contract/41_boundaries')
    public=oracle.public_program_identity()
    oracle._equal(len(public['selected_extent_sha256']),51,'contract/closed51_public_sites')
    return {'schemaVersion':1,'milestone':'M2by','passed':True,'classification':'IndependentStaticCalRtContract_NotRuntimeEvidence',
        'casesPerDomain':16,'retirementsPerDomain':656,'publicProgramSha256':public['program_sha256'],
        'actualCpuExecutions':0,'nativeCallerSchedulerEstablished':False,'firmwareReady':False}
